import { describe, expect, it } from "vitest";
import { attachControl } from "@babylonjs/lite";
import { attachFastOrbit } from "./fast-orbit.js";

function makeCanvas() {
    const map = new Map<string, Set<unknown>>();
    return {
        map,
        addEventListener(ev: string, h: unknown) { if (!map.has(ev)) map.set(ev, new Set()); map.get(ev)!.add(h); },
        removeEventListener(ev: string, h: unknown) { map.get(ev)?.delete(h); },
        setPointerCapture() {},
        releasePointerCapture() {},
        count() { let n = 0; for (const s of map.values()) n += s.size; return n; },
        fire(ev: string, e: object) { for (const h of [...(map.get(ev) ?? [])]) (h as (e: object) => void)(e); },
    } as any;
}
function makeCamera(sens = 1000) {
    return { alpha: 0, beta: 1, radius: 10, angularSensibility: sens, panningSensibility: 50, wheelPrecision: 3,
        inertia: 0.9, panningInertia: 0.9, inertialAlphaOffset: 0, inertialBetaOffset: 0, inertialRadiusOffset: 0,
        inertialPanningX: 0, inertialPanningY: 0, target: { x: 0, y: 0, z: 0 } } as any;
}
function drag(canvas: any, dx: number, dy: number) {
    canvas.fire("pointerdown", { button: 0, pointerType: "mouse", pointerId: 1, clientX: 0, clientY: 0 });
    canvas.fire("pointermove", { pointerType: "mouse", pointerId: 1, clientX: dx, clientY: dy });
    canvas.fire("pointerup", { pointerId: 1 });
}

describe("fastOrbit", () => {
    it("doubles drag and glide, leaves wheel alone, cleans up", () => {
        const canvasA = makeCanvas(); const camA = makeCamera(); const sceneA: any = { _beforeRender: [] };
        const detachA = attachControl(camA, canvasA, sceneA);
        drag(canvasA, 10, -6);
        const baseA = camA.inertialAlphaOffset, baseB = camA.inertialBetaOffset;
        // glide: run frames
        for (let i = 0; i < 5; i++) sceneA._beforeRender.forEach((f: () => void) => f());
        const baseAlpha = camA.alpha, baseBeta = camA.beta;
        detachA();

        const canvasB = makeCanvas(); const camB = makeCamera(); const sceneB: any = { _beforeRender: [] };
        const detachB = attachFastOrbit(camB, canvasB, sceneB);
        expect(camB.angularSensibility).toBe(500);
        drag(canvasB, 10, -6);
        expect(camB.inertialAlphaOffset).toBeCloseTo(baseA * 2, 12);
        expect(camB.inertialBetaOffset).toBeCloseTo(baseB * 2, 12);
        for (let i = 0; i < 5; i++) sceneB._beforeRender.forEach((f: () => void) => f());
        expect(camB.alpha).toBeCloseTo(baseAlpha * 2 + 0 * 0 - 0, 6 - 0);
        expect(camB.beta - 1).toBeCloseTo((baseBeta - 1) * 2, 6);
        expect(sceneB._beforeRender.length).toBe(1);
        expect(canvasB.count()).toBe(11);

        // wheel unchanged
        const radiusBefore = camB.radius;
        canvasB.fire("wheel", { deltaY: 100, preventDefault() {} });
        expect(camB.inertialRadiusOffset).toBeCloseTo(-(100 * radiusBefore) / 3000, 12);

        detachB(); detachB();
        expect(canvasB.count()).toBe(0);
        expect(sceneB._beforeRender.length).toBe(0);
        expect(camB.angularSensibility).toBe(1000);
    });
    it("keeps user-changed sensibility on detach", () => {
        const canvas = makeCanvas(); const cam = makeCamera(); const scene: any = { _beforeRender: [] };
        const detach = attachFastOrbit(cam, canvas, scene);
        cam.angularSensibility = 300;
        detach();
        expect(cam.angularSensibility).toBe(300);
    });
});
EOF
